import React, { useState, useEffect } from 'react';
import { scheduleService, courseService } from '../../services/api';
import { toast } from 'react-toastify';
import { FiPlus, FiTrash2, FiX, FiCalendar } from 'react-icons/fi';

const Schedules = () => {
  const [schedules, setSchedules] = useState([]);
  const [rooms, setRooms] = useState([]);
  const [courses, setCourses] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showModal, setShowModal] = useState(false);
  const [formData, setFormData] = useState({
    courseId: '', roomId: '', dayOfWeek: 'MONDAY', startTime: '08:00', endTime: '10:00', semester: 'S1', type: 'LECTURE'
  });

  const days = ['MONDAY', 'TUESDAY', 'WEDNESDAY', 'THURSDAY', 'FRIDAY', 'SATURDAY'];
  const dayLabels = { MONDAY: 'Lundi', TUESDAY: 'Mardi', WEDNESDAY: 'Mercredi', THURSDAY: 'Jeudi', FRIDAY: 'Vendredi', SATURDAY: 'Samedi' };

  useEffect(() => { fetchData(); }, []);

  const fetchData = async () => {
    try {
      const [schedulesRes, roomsRes, coursesRes] = await Promise.all([
        scheduleService.getAll(),
        scheduleService.getRooms().catch(() => ({ data: [] })),
        courseService.getAll().catch(() => ({ data: [] }))
      ]);
      setSchedules(schedulesRes.data);
      setRooms(roomsRes.data);
      setCourses(coursesRes.data);
    } catch (error) {
      toast.error('Erreur lors du chargement');
    } finally {
      setLoading(false);
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      await scheduleService.create({
        ...formData,
        courseId: parseInt(formData.courseId),
        roomId: formData.roomId ? parseInt(formData.roomId) : null
      });
      toast.success('Créneau créé avec succès');
      fetchData();
      closeModal();
    } catch (error) {
      toast.error(error.response?.data?.message || 'Erreur lors de la création');
    }
  };

  const handleDelete = async (id) => {
    if (window.confirm('Supprimer ce créneau ?')) {
      try {
        await scheduleService.delete(id);
        toast.success('Créneau supprimé');
        fetchData();
      } catch (error) {
        toast.error('Erreur lors de la suppression');
      }
    }
  };

  const closeModal = () => { setShowModal(false); };

  const getCourseName = (courseId) => courses.find(c => c.id === courseId)?.name || '-';
  const getRoomName = (roomId) => rooms.find(r => r.id === roomId)?.name || '-';

  if (loading) return <div className="loading"><div className="spinner"></div></div>;

  return (
    <div>
      <div className="header">
        <h1 className="page-title">Emploi du Temps</h1>
        <button className="btn btn-primary" onClick={() => setShowModal(true)}><FiPlus /> Ajouter un créneau</button>
      </div>

      {/* Schedule Grid */}
      <div className="card">
        <div className="table-container">
          <table className="table">
            <thead>
              <tr>
                <th>Jour</th>
                <th>Horaire</th>
                <th>Cours</th>
                <th>Salle</th>
                <th>Type</th>
                <th>Actions</th>
              </tr>
            </thead>
            <tbody>
              {schedules.length > 0 ? schedules.map((schedule) => (
                <tr key={schedule.id}>
                  <td>{dayLabels[schedule.dayOfWeek] || schedule.dayOfWeek}</td>
                  <td>{schedule.startTime} - {schedule.endTime}</td>
                  <td>{getCourseName(schedule.courseId)}</td>
                  <td>{getRoomName(schedule.roomId)}</td>
                  <td><span className="badge badge-info">{schedule.type}</span></td>
                  <td>
                    <button className="btn btn-danger btn-sm" onClick={() => handleDelete(schedule.id)}><FiTrash2 /></button>
                  </td>
                </tr>
              )) : (
                <tr><td colSpan="6" style={{ textAlign: 'center', color: '#64748b' }}>Aucun créneau trouvé</td></tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* Rooms Section */}
      <div className="card" style={{ marginTop: '24px' }}>
        <div className="card-header">
          <h2 className="card-title">Salles disponibles</h2>
        </div>
        <div className="table-container">
          <table className="table">
            <thead>
              <tr><th>Code</th><th>Nom</th><th>Bâtiment</th><th>Capacité</th><th>Type</th><th>Disponible</th></tr>
            </thead>
            <tbody>
              {rooms.length > 0 ? rooms.map((room) => (
                <tr key={room.id}>
                  <td>{room.roomCode}</td>
                  <td>{room.name}</td>
                  <td>{room.building || '-'}</td>
                  <td>{room.capacity} places</td>
                  <td>{room.type}</td>
                  <td><span className={`badge badge-${room.isAvailable ? 'success' : 'danger'}`}>{room.isAvailable ? 'Oui' : 'Non'}</span></td>
                </tr>
              )) : (
                <tr><td colSpan="6" style={{ textAlign: 'center', color: '#64748b' }}>Aucune salle trouvée</td></tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      {showModal && (
        <div className="modal-overlay" onClick={closeModal}>
          <div className="modal" onClick={(e) => e.stopPropagation()}>
            <div className="modal-header">
              <h2 className="modal-title">Ajouter un créneau</h2>
              <button className="modal-close" onClick={closeModal}><FiX /></button>
            </div>
            <form onSubmit={handleSubmit}>
              <div className="form-group">
                <label className="form-label">Cours</label>
                <select className="form-select" value={formData.courseId} onChange={(e) => setFormData({ ...formData, courseId: e.target.value })} required>
                  <option value="">Sélectionner un cours</option>
                  {courses.map(c => <option key={c.id} value={c.id}>{c.courseCode} - {c.name}</option>)}
                </select>
              </div>
              <div className="form-group">
                <label className="form-label">Salle</label>
                <select className="form-select" value={formData.roomId} onChange={(e) => setFormData({ ...formData, roomId: e.target.value })}>
                  <option value="">Sélectionner une salle</option>
                  {rooms.filter(r => r.isAvailable).map(r => <option key={r.id} value={r.id}>{r.roomCode} - {r.name}</option>)}
                </select>
              </div>
              <div className="form-group">
                <label className="form-label">Jour</label>
                <select className="form-select" value={formData.dayOfWeek} onChange={(e) => setFormData({ ...formData, dayOfWeek: e.target.value })}>
                  {days.map(d => <option key={d} value={d}>{dayLabels[d]}</option>)}
                </select>
              </div>
              <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '16px' }}>
                <div className="form-group">
                  <label className="form-label">Début</label>
                  <input type="time" className="form-control" value={formData.startTime} onChange={(e) => setFormData({ ...formData, startTime: e.target.value })} required />
                </div>
                <div className="form-group">
                  <label className="form-label">Fin</label>
                  <input type="time" className="form-control" value={formData.endTime} onChange={(e) => setFormData({ ...formData, endTime: e.target.value })} required />
                </div>
              </div>
              <div style={{ display: 'flex', gap: '12px', justifyContent: 'flex-end' }}>
                <button type="button" className="btn btn-secondary" onClick={closeModal}>Annuler</button>
                <button type="submit" className="btn btn-primary">Créer</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default Schedules;
